#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Work from the project folder, wherever the script was started from.
cd "$(dirname "$0")/.."

TOTAL_STAGES=7

banner "AI Coach proxy setup (shared Anthropic key)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
say "The proxy runs as a Supabase Edge Function, so it needs a Supabase project."
say "Free plan is enough. The project also keeps the daily usage counter."
open_url "https://supabase.com/dashboard/new"
step "Sign in (or create an account), then fill in New project:"
step "  Name: leadership-portal · Region: the one closest to Dakar (e.g. West EU)"
step "  Database password: generate one and SAVE it in your password manager;"
step "  the CLI asks for it in stage 3."
step "Click Create new project and wait until it shows as ready (about a minute)."
step "Look at the address bar: https://supabase.com/dashboard/project/<REF>/..."
ask SUPABASE_PROJECT_REF "Paste the project ref (the 20 letters after /project/):"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase CLI: install and sign in"
if command -v supabase >/dev/null 2>&1; then
  say "Supabase CLI found: $(supabase --version 2>/dev/null | head -1)"
else
  say "Installing the Supabase CLI with Homebrew (official tap)."
  if confirm "Run: brew install supabase/tap/supabase ?"; then
    brew install supabase/tap/supabase
  else
    warn "Install it yourself, then re-run this wizard: https://supabase.com/docs/guides/local-development/cli/getting-started"
    exit 1
  fi
fi
say "Now sign in. A browser window asks you to approve the CLI."
pause "Press Enter to run: supabase login"
supabase login

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Link the project and create the usage table"
if [[ ! -f supabase/config.toml ]]; then
  say "Creating the local Supabase config (answer the prompts; defaults are fine)."
  supabase init
fi
say "Linking this folder to project $SUPABASE_PROJECT_REF. Enter the database password from stage 1 when asked."
supabase link --project-ref "$SUPABASE_PROJECT_REF"
say "Applying supabase/migrations (creates the ai_usage table and its function)."
supabase db push
say "Done. The table is private: only the proxy can read or write it."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Secrets: Anthropic key, access code, allowed origins"
say "The key goes straight to Supabase as a server secret. It is NOT saved in .env"
say "and never in the repo."
open_url "https://platform.claude.com/settings/keys"
step "Create Key → name it leadership-portal-proxy → copy it (shown once)."
ask_secret ANTHROPIC_API_KEY "Paste the Anthropic key (hidden):"
say ""
say "The access code is what participants type once in the AI Coach tab."
say "Make it long; share it only inside the cohort. If it leaks, re-run this stage"
say "with a new code and participants enter the new one."
SUGGESTED_CODE="$(openssl rand -base64 18 | tr -d '/+=' | cut -c1-20)"
say "Suggested code: $SUGGESTED_CODE"
ask ACCESS_CODE "Access code to use (Enter for the suggestion):" || true
[[ -z "${ACCESS_CODE:-}" ]] && ACCESS_CODE="$SUGGESTED_CODE"
write_env ACCESS_CODE "$ACCESS_CODE"
ask ALLOWED_ORIGINS "Allowed origins (Enter keeps):" || true
[[ -z "${ALLOWED_ORIGINS:-}" ]] && ALLOWED_ORIGINS="https://mbagayoko1.github.io,http://localhost:3005"
write_env ALLOWED_ORIGINS "$ALLOWED_ORIGINS"
SECRETS_FILE="$(mktemp)"; chmod 600 "$SECRETS_FILE"
printf 'ANTHROPIC_API_KEY=%s\nACCESS_CODE=%s\nALLOWED_ORIGINS=%s\n' "$ANTHROPIC_API_KEY" "$ACCESS_CODE" "$ALLOWED_ORIGINS" > "$SECRETS_FILE"
supabase secrets set --env-file "$SECRETS_FILE"
rm -f "$SECRETS_FILE"
unset ANTHROPIC_API_KEY
say "Secrets stored on Supabase."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Deploy the proxy and test it"
say "Deploying supabase/functions/ai-coach (bundled by Supabase; no Docker needed)."
say "The access code is the gate, so the"
say "function is deployed without Supabase JWT checks."
supabase functions deploy ai-coach --no-verify-jwt --use-api
PROXY_URL="https://${SUPABASE_PROJECT_REF}.supabase.co/functions/v1/ai-coach"
write_env VITE_AI_PROXY_URL "$PROXY_URL"
say "Testing: a wrong code must be refused (401), the real one accepted (204)."
ORIGIN_FOR_TEST="${ALLOWED_ORIGINS%%,*}"
bad=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H "Origin: $ORIGIN_FOR_TEST" -H "x-portal-code: wrong-code" "$PROXY_URL/v1/check" || true)
good=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H "Origin: $ORIGIN_FOR_TEST" -H "x-portal-code: $ACCESS_CODE" "$PROXY_URL/v1/check" || true)
say "wrong code → $bad   real code → $good"
if [[ "$bad" == "401" && "$good" == "204" ]]; then
  say "The proxy answers correctly."
else
  warn "Unexpected result. Check: supabase functions logs ai-coach"
  SKIPPED+=("Proxy test did not pass (wrong=$bad, real=$good); check the function logs")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Anthropic: cap the monthly spend"
say "If the access code ever leaks, this is the hard limit on what it can cost."
open_url "https://console.anthropic.com/settings/limits"
step "Set a monthly spend limit for the organisation (for a cohort of 20, 50–100 USD"
step "is plenty) and turn on the email alert."
note "The proxy also stops after 400 requests or 800k output tokens per day."
pause "Press Enter once the limit is set"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Build the site with the proxy address"
say "The site must be rebuilt so it knows the proxy address (it is read from .env"
say "at build time; the address is public, the key is not)."
if confirm "Build now and publish to GitHub Pages (npm run deploy)?"; then
  npm run deploy
  say "Published. Open the live site, go to AI Coach and enter the access code."
else
  SKIPPED+=("Build and publish: npm run deploy")
  note "Locally: restart the dev server so it picks up .env, then open the AI Coach tab."
fi

finish
say "Give participants the access code (it is in .env as ACCESS_CODE, nowhere else)."
say "To change the code later: re-run stage 4 by running this wizard again."
}

run_wizard "$@"; exit
